import{z as n,x as o,o as A,c as d,q as i,j as t,D as a,d as B,s,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"优化库的对照","description":"","frontmatter":{"title":"优化库的对照","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/sc-optimizer-libraries.md","filePath":"cs/sc-optimizer-libraries.md","lastUpdated":1791413859000}'),F={name:"cs/sc-optimizer-libraries.md"};function p(m,E,c,C,D,h){const r=o("Mermaid");return A(),d("div",null,[E[2]||(E[2]=i('<h1 id="优化库的对照" tabindex="-1">优化库的对照 <a class="header-anchor" href="#优化库的对照" aria-label="Permalink to &quot;优化库的对照&quot;">​</a></h1><div class="epigraph"><p>优化库不是算法排名表，而是合同分类表；失败时要能指认违约的是哪一条——导数、问题类、停止准则，还是缩放。</p><footer>—— 据 Nocedal and Wright, Numerical Optimization, Springer, 2006 整理</footer></div><p><a href="/cs/sc-random-generation">上一课</a>给了可命名、可复现的随机源——多起点的原料。本课对照数值软件里最大的门类：优化库。主干已给<a href="/cs/newton-nonlinear">非线性方程与牛顿</a>、<a href="/cs/iterative-solver-converge">迭代法何时收敛</a>与<a href="/cs/condition-number">条件数</a>；缺口不是再讲一遍算法，而是把「库与库的差别」归到几条合同轴上，让失败可以归因，而不是落在「这个库不行」的口头上。本课后，数值与科学计算的工具链就齐了。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>同一个问题，L-BFGS 收了，牛顿库发散，内点法报「不可行」；换一组缩放又全部反转。没有合同语言时，这些现象无法归因。缺口是把四件事拆成独立可换的选项：交出去什么（函数、梯度、Hessian 或都没有）、问题属于哪一类（光滑无约束、最小二乘、线性与锥规划）、算法族怎么停、变量怎么缩放。失败先归因到轴，再归因到库。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>轴一，导数供给：解析手写、自动微分（上一课的合同），或有限差分。前向差分要 \\(n+1\\) 次函数求值，且梯度相对精度只有 \\(u^{1/2}\\) 量级；中心差分提到 \\(u^{2/3}\\)，代价翻倍。梯度里的噪声直接封顶可达精度——合同从这里开始就不同库。</p><p><span class="marginnote">差分步长有最优值：前向差分取 \\(h\\approx u^{1/2}\\)，误差被截断与舍入两头夹住；病态问题里 Hessian 的条件数再把这个噪声放大进梯度——可达解的精度跟着封顶。这条账是「梯度必须由 AD 或解析供给」的最硬理由。</span></p><p>轴二，问题类与算法族：大规模光滑无约束，L-BFGS 用最近 \\(m\\) 步的曲率历史近似逆 Hessian，存储 \\(O(mn)\\)，是默认起点（Liu 与 Nocedal, 1989）；最小二乘用 Gauss-Newton 与 Levenberg-Marquardt，MINPACK 是参考实现（Moré, 1977）；非线性约束进内点法，IPOPT 的滤子线搜索是代表（Wächter 与 Biegler, 2006）；大规模二次规划，一阶 ADMM 的 OSQP 用中等精度与热启动换每次迭代的便宜（Stellato et al., 2020）。轴三，停止与缩放：梯度无穷范数的容差要连同 \\(\\kappa\\) 读——病态时梯度范数天然大，收紧容差只烧迭代；变量量纲差几个数量级，先平衡再进库，缩放是调用方的责任，不是库的魔法。</p>',9)),(A(),t(l,null,{default:a(()=>[s(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20PROB%5B%22%E9%97%AE%E9%A2%98%E4%B8%8E%E6%95%B0%E6%8D%AE%EF%BC%9A%E7%BC%A9%E6%94%BE%22%5D%20--%3E%20GRAD%5B%22%E5%AF%BC%E6%95%B0%E4%BE%9B%E7%BB%99%EF%BC%9A%E8%A7%A3%E6%9E%90%20%2F%20AD%20%2F%20%E5%B7%AE%E5%88%86%22%5D%0A%20%20GRAD%20--%3E%20CLASS%5B%22%E9%97%AE%E9%A2%98%E7%B1%BB%EF%BC%9A%E6%97%A0%E7%BA%A6%E6%9D%9F%20%2F%20%E6%9C%80%E5%B0%8F%E4%BA%8C%E4%B9%98%20%2F%20%E8%A7%84%E5%88%92%22%5D%0A%20%20CLASS%20--%3E%20ALG%5B%22%E7%AE%97%E6%B3%95%E6%97%8F%EF%BC%9AL-BFGS%20%2F%20LM%20%2F%20%E5%86%85%E7%82%B9%20%2F%20ADMM%22%5D%0A%20%20ALG%20--%3E%20STOP%5B%22%E5%81%9C%E6%AD%A2%E5%87%86%E5%88%99%EF%BC%9A%E5%AE%B9%E5%B7%AE%E4%B8%8E%E6%9D%A1%E4%BB%B6%E6%95%B0%E4%B8%80%E8%B5%B7%E8%AF%BB%22%5D%0A%20%20STOP%20--%3E%20VERDICT%5B%22%E5%A4%B1%E8%B4%A5%E5%BD%92%E5%9B%A0%EF%BC%9A%E8%BF%9D%E7%BA%A6%E5%9C%A8%E5%93%AA%E6%9D%A1%E8%BD%B4%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[B("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,[e("span",{class:"marginnote"},"L-BFGS 里的「BFGS」是四位提出者的姓名首字母，「L」是 limited-memory：不存 \\(n\\times n\\) 的逆 Hessian，只保留最近 \\(m\\) 步的曲率差。数字实例：\\(n=10^5\\)、\\(m=10\\) 时存储约 \\(2mn=2\\times 10^6\\) 个数（几 MB），而不是 \\(10^{10}\\) 个数（几十 GB）——大规模无约束优化的默认起点由此而来。")],-1)),(A(),t(l,null,{default:a(()=>[s(r,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20LR%0A%20%20SRC%7B%22%E6%A2%AF%E5%BA%A6%E4%BB%8E%E5%93%AA%E6%9D%A5%3F%22%7D%20--%3E%7C%22%E8%A7%A3%E6%9E%90%20%2F%20%E8%87%AA%E5%8A%A8%E5%BE%AE%E5%88%86%22%7C%20CLEAN%5B%22%E6%A2%AF%E5%BA%A6%E5%B9%B2%E5%87%80%E5%8F%AF%E9%9D%A0%22%5D%0A%20%20SRC%20--%3E%7C%22%E6%9C%89%E9%99%90%E5%B7%AE%E5%88%86%22%7C%20NOISY%5B%22%E6%A2%AF%E5%BA%A6%E5%B8%A6%20u%5E1%2F2%20%E7%BA%A7%E5%99%AA%E5%A3%B0%22%5D%0A%20%20CLEAN%20--%3E%20LS%5B%22%E7%BA%BF%E6%90%9C%E7%B4%A2%E6%97%8F%E5%8F%AF%E7%94%A8%EF%BC%9AL-BFGS%22%5D%0A%20%20CLEAN%20--%3E%20TR%5B%22%E4%BF%A1%E4%BB%BB%E5%9F%9F%E6%97%8F%E5%8F%AF%E7%94%A8%EF%BC%9ALM%20%2F%20%E5%86%85%E7%82%B9%22%5D%0A%20%20NOISY%20--%3E%20TR2%5B%22%E5%8F%AA%E5%89%A9%E4%BF%A1%E4%BB%BB%E5%9F%9F%E6%97%8F%E5%85%9C%E5%BE%97%E4%BD%8F%E5%99%AA%E5%A3%B0%22%5D%0A%20%20NOISY%20--%3E%20NM%5B%22%E6%88%96%E9%80%80%E5%88%B0%20Nelder-Mead%EF%BC%9A%E4%BD%8E%E7%BB%B4%E5%B0%8F%E9%97%AE%E9%A2%98%22%5D%0A%20%20LS%20--%3E%20ACC%5B%22%E5%8F%AF%E8%BE%BE%E7%B2%BE%E5%BA%A6%E7%94%B1%E6%A2%AF%E5%BA%A6%E5%99%AA%E5%A3%B0%E5%B0%81%E9%A1%B6%22%5D%0A%20%20TR%20--%3E%20ACC%0A%20%20TR2%20--%3E%20ACC%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=i('<p>对照按族不按库，因为同族共享失败模式。<span class="marginnote">初学者容易以为线搜索比信任域「落后」，实际上两族分界在输入质量：线搜索沿一个方向反复试探能走多远，前提是方向可靠；信任域先限定「模型在多大半径内可信」，噪声进来时不会小步乱撞。所以梯度是差分给的时候，先选族，再谈调参。</span><span class="marginnote">数字实例：把对偶间隙从 \\(10^{-4}\\) 压到 \\(10^{-8}\\)，内点法通常多解几次线性系就到；ADMM 要多出几个数量级的迭代——OSQP 的合同写明「中等精度」，要 \\(10^{-8}\\) 的场合换内点法，不是把参数调到冒烟就能补的。</span>线搜索族怕非光滑与噪声：梯度是差分给的时候，线搜索在噪声里小步徘徊；信任域族用模型可信半径兜住同一种噪声——两族的分界不是好坏，是输入质量。内点与 ADMM 的分工是精度换速度：内点每次迭代解一个线性系、把对偶间隙压到 \\(10^{-8}\\) 量级；ADMM 迭代便宜但只能给中等精度，且要为热启动付分裂变量的账。Nelder-Mead 单纯形不要求导数，代价是低维与特定条件下才有收敛结论（Lagarias et al., 1998），用在 \\(n\\) 大或要精度的问题上是合同错配。多起点接上一课：起点流的命名与分工，决定「哪个起点找到的解」能不能写进报告。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不进随机与随机梯度族——那是大模型栏的对象；不讲全局优化与分支定界，也不做跨库跑分——评测方法论另有课题。库的默认停止准则几乎总是过松或过紧，属于要显式设置的合同项。后课默认：优化调用先写清四条轴，失败先查轴再查库。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>合同四轴：导数供给、问题类、算法族、停止与缩放；失败先归因到轴。</li><li>差分梯度只有 \\(u^{1/2}\\) 到 \\(u^{2/3}\\) 级精度，病态时封顶可达解精度。</li><li>L-BFGS 是大规模无约束默认；LM 管最小二乘；内点与 ADMM 用精度换迭代成本。</li><li>Nelder-Mead 缺一般收敛理论，是合同错配的高发区。</li><li>出处：Nocedal and Wright, 2006；Liu and Nocedal, 1989；Moré, 1977；Wächter and Biegler, 2006；Stellato et al., 2020。</li></ul>',5))])}const L=n(F,[["render",p]]);export{S as __pageData,L as default};
